variables.real_high_count:
{% set ns = namespace(n=0) %}
{% for z in ['sklep_michal','prizemi_michal','prizemi_chodba_zachod','1p_jidelna','1p_kuchyn','1p_koupelna','1p_chodba','2p_mama'] %}
  {% if ('climate.' ~ z) != support_zone
        and is_state('binary_sensor.zona_' ~ z ~ '_aktivni','on')
        and (states('sensor.zona_' ~ z ~ '_demand') | float(0)) >= (original_threshold | float(70)) %}
    {% set ns.n = ns.n + 1 %}
  {% endif %}
{% endfor %}
{{ ns.n }}
